import os,sys,subprocess,base64,time
W="/tmp/ncm_workspace"; os.makedirs(W,exist_ok=True); OUT="/kaggle/working/results"; os.makedirs(OUT,exist_ok=True)
def sh(c): print("$",c[:200],flush=True); r=subprocess.run(c,shell=True); print("rc",r.returncode,flush=True)
sh("pip install -q omegaconf hydra-core einops sacrebleu rouge_score")
if not os.path.exists(W+"/ncm"): sh(f"git clone -q https://github.com/HazyResearch/ncm.git {W}/ncm")
F={"aug_sudoku.py":"","build_ext.py":"",'apc_lib.py': '', 'apc_v4.py': '', 'run_v5.py': '', 'probe.py': '', 'dagger_aug.py': '', 'perturb.py': ''}
for n,b in F.items(): open(W+"/"+n,"wb").write(base64.b64decode(b))
from huggingface_hub import snapshot_download as _sd
def sd(*a,**k):
    for i in range(8):
        try: return _sd(*a,**k)
        except Exception as e: print("retry",i,e,flush=True); time.sleep(30)
    return _sd(*a,**k)
hf="xsum"
ck=sd("hazyresearch/ncm-checkpoints",allow_patterns=[hf+"/*"],local_dir=W+"/ck")+"/"+hf
dd=sd("hazyresearch/ncm-datasets",repo_type="dataset",allow_patterns=[hf+"/*"],local_dir=W+"/data")+"/"+hf
sh("cd "+W+" && python build_ext.py xsum "+dd+" "+W+"/ext.pickle")
ENV="cd "+W+" && PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True NCM_ROOT="+W+"/ncm "
for c in ['python run_v5.py --task xsum --ck {ck} --dd {dd} --ext {ext} --out {out}/xsum --n_train 3000 --n_val 998 --bs 32 --epochs 10', 'python probe.py --task xsum --ck {ck} --dd {dd} --ext {ext} --out {out}/xsum-probe --n_train 3000 --n_val 998 --bs 32']:
    sh(ENV+c.format(ck=ck,dd=dd,ext=W+"/ext.pickle",out=OUT)+" 2>&1 | grep -v Warning")
